  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#e0f7fa");
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Sun
  brush.fill("#ff9900");
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(250, 50);
  brush.vertex(200, 100);
  brush.endShape(true);

  // Hills
  brush.fill("#6a3d1e");
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Clouds
  brush.fill("#e0f7fa");
  brush.beginShape();
  brush.vertex(100, 150);
  brush.vertex(150, 100);
  brush.vertex(200, 150);
  brush.vertex(150, 200);
  brush.endShape(true);
}
