  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB"); // Sky blue
  brush.fillBleed(0.5); // Bleed effect
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Hills
  brush.fill("#4682B4"); // Green
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700"); // Yellow
  brush.fillBleed(0.2);
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(220, 50);
  brush.vertex(240, 70);
  brush.vertex(220, 110);
  brush.endShape(true);
}

