  vertex(0, 200);
  vertex(400, 200);
  vertex(400, 250);
  vertex(0, 250);
  endShape(true);

  // Sun
  fill("#ff4500"); // Orange
  fillBleed(0.8);
  beginShape();
  vertex(200, 100);
  vertex(250, 80);
  vertex(250, 100);
  vertex(200, 120);
  endShape(true);
}
